@using sv_ac6d7d2fdd3d428c97a9536e5836c845.Services

<div class="message-area">
    @if (Channel is not null)
    {
        <div class="message-area-header">
            <h5># @Channel.Name</h5>
            <span class="channel-description">@Channel.Description</span>
        </div>

        <div class="message-list" @onscroll="HandleScroll">
            @if (IsLoadingMore)
            {
                <div class="loading-more text-center py-2">
                    <span class="spinner-border spinner-border-sm" role="status"></span>
                    Loading older messages…
                </div>
            }
            @if (HasMoreMessages)
            {
                <div class="text-center py-2">
                    <button class="btn btn-sm btn-outline-secondary" @onclick="OnLoadMore">Load older messages</button>
                </div>
            }
            @foreach (var msg in Messages)
            {
                <MessageItem Message="msg"
                             ThreadSummary="GetThreadSummary(msg.Id)"
                             OnOpenThread="OnOpenThread"
                             OnReact="OnReact" />
            }
        </div>

        <MessageInput Placeholder="Message #@Channel.Name"
                      ButtonLabel="Send"
                      OnSubmit="OnSendMessage" />
    }
    else
    {
        <div class="no-channel-selected">
            <p class="text-muted">Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnSendMessage { get; set; }

    private ThreadSummary? GetThreadSummary(int messageId) =>
        ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top detection is best handled via JS interop;
        // we provide the "Load older messages" button as a reliable fallback.
    }
}
"}

