@page "/chat"
@namespace sv_ac6d7d2fdd3d428c97a9536e5836c845.Components.Pages.Chat
@rendermode InteractiveServer
@using sv_ac6d7d2fdd3d428c97a9536e5836c845.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelList Channels="_channels"
                     SelectedChannelId="_selectedChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(_threadRootMessage is null ? "full-width" : "")">
        <MessageArea Channel="_selectedChannel"
                     Messages="_messages"
                     ThreadSummaries="_threadSummaries"
                     HasMoreMessages="_hasMoreMessages"
                     IsLoadingMore="_isLoadingMore"
                     OnLoadMore="LoadMoreMessages"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage" />
    </div>

    @if (_threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply"
                         OnReact="HandleReaction" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private Channel? _selectedChannel;
    private int _selectedChannelId;
    private bool _hasMoreMessages;
    private bool _isLoadingMore;

    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        CloseThreadSync();

        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _hasMoreMessages = _messages.Count == PageSize;
        BuildThreadSummaries();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update the channel's unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadMoreMessages()
    {
        if (_isLoadingMore || _selectedChannel is null) return;

        _isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, PageSize);
        _hasMoreMessages = older.Count == PageSize;
        _messages.InsertRange(0, older);
        BuildThreadSummaries();
        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage is null) return;

        var threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadReplies = threadMessages.Where(m => m.Id != rootMessageId).ToList();
    }

    private void CloseThreadSync()
    {
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private Task CloseThread()
    {
        CloseThreadSync();
        return Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        BuildThreadSummaries();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the local message
        UpdateReactionOnMessage(_messages, args.MessageId, args.Emoji);
        UpdateReactionOnMessage(_threadReplies, args.MessageId, args.Emoji);
        if (_threadRootMessage?.Id == args.MessageId)
        {
            AddReactionToMessage(_threadRootMessage, args.Emoji);
        }
    }

    private static void UpdateReactionOnMessage(List<Message> messages, int messageId, string emoji)
    {
        var idx = messages.FindIndex(m => m.Id == messageId);
        if (idx >= 0)
        {
            AddReactionToMessage(messages[idx], emoji);
        }
    }

    private static void AddReactionToMessage(Message message, string emoji)
    {
        var existing = message.Reactions.FirstOrDefault(r => r.Emoji == emoji);
        if (existing is not null)
        {
            if (!existing.Users.Contains("You"))
                existing.Users.Add("You");
        }
        else
        {
            message.Reactions.Add(new Reaction(emoji, ["You"]));
        }
    }

    private void BuildThreadSummaries()
    {
        // Identify messages that are thread roots (have replies referencing them)
        var replyGroups = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value);

        _threadSummaries = replyGroups
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
    }
}

